// Loads /menu.json (generated by build-menu.js) and fills:
//   #menu       – the top navigation
//   #tool-list  – the list of tools on the home page (optional)
(async () => {
  let items = [];
  try {
    items = await (await fetch("/menu.json")).json();
  } catch (e) {
    return;
  }

  const menu = document.getElementById("menu");
  if (menu) {
    for (const item of items) {
      const a = document.createElement("a");
      a.href = item.path;
      a.textContent = item.title;
      if (location.pathname === item.path || location.pathname === item.path.slice(0, -1)) {
        a.setAttribute("aria-current", "page");
      }
      menu.appendChild(a);
    }
  }

  const list = document.getElementById("tool-list");
  if (list) {
    for (const item of items) {
      const a = document.createElement("a");
      a.href = item.path;
      const title = document.createElement("strong");
      title.textContent = item.title;
      const desc = document.createElement("span");
      desc.textContent = item.description;
      a.append(title, desc);
      list.appendChild(a);
    }
  }
})();
